function tone(freq,duration=.08,type='sine',gain=.07){if(!audioEnabled)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const osc=audioContext.createOscillator(),amp=audioContext.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioContext.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.35),audioContext.currentTime+duration);amp.gain.setValueAtTime(gain,audioContext.currentTime);amp.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(amp);amp.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration)}catch{}}
function clearKeys(){doubleTap.reset();Object.keys(keys).forEach(k=>keys[k]=false);syncPads()}
