function events(){for(const event of game.events){if(event.type==='dash'){tone(130,.12,'triangle',.03);toast('SCATTO')}if(event.type==='round'){camera.reset(game.fighters);fireballs=[];blades=[];}if(event.type==='swing')tone(180,.08,'triangle',.025);if(event.type==='special'){tone(90,.22,'sawtooth',.08);toast('ABILITÀ SPECIALE');spawnFireball(event.id);spawnBlade(event.id)}if(event.type==='hit'||event.type==='block'){const blocked=event.type==='block';shake=blocked?3:8;flash[event.id]=.14;tone(blocked?650:100,blocked?.05:.13,blocked?'triangle':'sawtooth',.06);for(let n=0;n<13;n++)particles.push({x:event.x,y:event.y,vx:(Math.random()-.5)*330,vy:(Math.random()-.5)*280,life:.28,color:blocked?'#d5e9df':'#f6b56d'});if(blocked)toast('PARATA · −2');else if(event.combo>=2)toast(event.combo+' COLPI · '+names[game.fighters[event.attacker].char]);else toast('COLPO A SEGNO · −'+event.damage)}if(event.type==='evade')toast('SCHIVATA RIUSCITA');if(event.type==='empty')toast('ENERGIA INSUFFICIENTE');if(event.type==='fight')tone(440,.22,'triangle');if(event.type==='roundEnd'){clearKeys();tone(event.winner===null?180:360,.4,'triangle');if(event.match){const winner=game.fighters[event.winner];$('winnerTitle').textContent=names[winner.char]+' VINCE';$('score').textContent=game.wins[0]+' — '+game.wins[1]+(game.mode==='cpu'?(event.winner===0?' · Hai conquistato l’arena.':' · La rivincita ti aspetta.'):' · Scontro concluso.');$('result').classList.remove('hidden');$('pause').disabled=true;$('status').textContent='Scontro concluso · Scegli Rivincita per giocare ancora.'}}}game.events=[]}
function background(t){const g=c.createLinearGradient(0,0,0,650);g.addColorStop(0,'#302239');g.addColorStop(1,'#c7a07b');c.fillStyle=g;c.fillRect(0,0,1200,650);if(scenery.complete&&scenery.naturalWidth){c.drawImage(scenery,-camera.left*camera.zoom,0,ARENA_WIDTH*camera.zoom,650)}const top=c.createLinearGradient(0,0,0,155);top.addColorStop(0,'#100c1ce0');top.addColorStop(1,'#100c1c00');c.fillStyle=top;c.fillRect(0,0,1200,155);for(let i=0;i<25;i++){const worldX=(i*137+t*24)%ARENA_WIDTH;const x=(worldX-camera.left)*camera.zoom;const y=140+((i*83+t*16)%440);c.save();c.translate(x,y);c.rotate(t*.5+i);c.fillStyle=i%2?'#f5a7b77a':'#ffd39266';c.beginPath();c.ellipse(0,0,3.5,1.6,0,0,Math.PI*2);c.fill();c.restore()}}
function imageFor(f){if(f.action==='special'){const prep=specialPrep[f.char===0?'demone':'ninja'];if(prep.length){const frame=Math.min(3,Math.floor(Math.min(.999,f.t/.68)*4));return prep[frame]}return images.punch[f.char][0]}if(f.action==='dash')return images.study[f.char][1];if(f.action==='kick'){const n=f.frame;return n===2||n===3?images.study[f.char][4]:n===1||n===4?images.study[f.char][0]:images.punch[f.char][0]}if(f.action==='idle')return f.walk>0&&Math.floor(f.walk*7)%2?images.study[f.char][1]:images.punch[f.char][0];return images[f.action][f.char][f.frame]}
function defeatInfo(f){if(!['roundOver','matchOver'].includes(game.phase)||game.roundWinner===null||f.id===game.roundWinner)return null;const sheet=defeatSheets[f.char===0?'demone':'ninja'];if(!sheet)return null;return{img:sheet.img,frame:Math.min(5,Math.floor(game.phaseT/.42)),w:sheet.img.width/6,h:sheet.img.height}}
function drawFighter(f){const defeat=defeatInfo(f);let image=defeat?defeat.img:imageFor(f),prep=!defeat&&f.action==='special'&&specialPrep[f.char===0?'demone':'ninja'].includes(image),w=defeat?324:(image.src.includes('/punch/')||prep?270:324),h=defeat?648:(image.src.includes('/punch/')||prep?405:459);let airborne=f.action==='jump'&&f.frame>=2&&f.frame<=3;c.save();c.fillStyle='#3c342b30';c.beginPath();c.ellipse(f.x,594,airborne?35:58,airborne?5:9,0,0,Math.PI*2);c.fill();c.translate(f.x,592);c.scale(f.dir,1);if(f.action==='dash'){c.rotate(f.dashDir*f.dir*.055);c.globalAlpha*=.95}if(f.stun>0)c.rotate(-.025);if(flash[f.id]>0){c.shadowColor='#ffc88a';c.shadowBlur=18}if(defeat)c.drawImage(image,defeat.frame*defeat.w,0,defeat.w,defeat.h,-w/2,-h,w,h);else c.drawImage(image,-w/2,-h,w,h);c.restore()}
function spawnFireball(id){const f=game.fighters[id];if(!f||f.char!==0)return;fireballs.push({id,x:f.x+f.dir*125,y:420,dir:f.dir,state:'travel',t:0,hit:false})}
