function explodeBlade(blade){if(blade.state!=='travel')return;blade.state='explode';blade.t=0;shake=Math.max(shake,10);for(let n=0;n<22;n++)particles.push({x:blade.x,y:blade.y,vx:(Math.random()-.5)*420,vy:(Math.random()-.5)*360,life:.42,color:n%2?'#79dfff':'#d9f7ff'})}
function updateBlades(dt){for(const blade of blades){blade.t+=dt;if(blade.state==='travel'){blade.x+=blade.dir*980*dt;const target=game.fighters[1-blade.id];if(!blade.hit&&target&&Math.abs(blade.x-target.x)<62){blade.hit=true;if(net.role!=='guest')game.hit(blade.id,1-blade.id,true)}if(blade.x<35||blade.x>ARENA_WIDTH-35)explodeBlade(blade)}else if(blade.state==='explode'&&blade.t>.42){blade.state='fade';blade.t=0}else if(blade.state==='fade'&&blade.t>.22)blade.dead=true}blades=blades.filter(blade=>!blade.dead)}
