function drawSpecial(){}
function hud(){if(!game.fighters.length)return;game.fighters.forEach((f,i)=>{$('name'+i).textContent=names[f.char];$('role'+i).textContent=i===0?'GIOCATORE 1':game.mode==='cpu'?'CPU':'GIOCATORE 2';$('life'+i).style.width=f.hp/160*100+'%';$('energy'+i).style.width=f.energy+'%';$('dash'+i).style.width=f.dashEnergy+'%';$('dots'+i).textContent=[0,1].map(n=>game.wins[i]>n?'●':'○').join(' ')});$('round').textContent='ROUND '+Math.max(1,game.round);$('timer').textContent=Math.ceil(game.timer).toString().padStart(2,'0');let text='';if(game.phase==='countdown')text=game.phaseT<1?'ROUND '+game.round:game.phaseT<1.7?'PRONTI?':'COMBATTI!';else if(game.phase==='fight'&&game.phaseT<.5)text='COMBATTI!';else if(game.phase==='roundOver')text=game.roundWinner===null?'PAREGGIO':names[game.fighters[game.roundWinner].char]+' VINCE IL ROUND';$('callout').textContent=text}
function render(t){c.clearRect(0,0,1200,650);c.save();if(shake>0)c.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);background(t);c.save();c.translate(600,592);c.scale(camera.zoom,camera.zoom);c.translate(-camera.x,-592);if(loaded){for(const f of game.fighters){if(f.action==='dash'){for(let i=3;i>0;i--){c.save();c.globalAlpha=.12/i;const ghost={...f,x:f.x-f.dashDir*i*32};drawFighter(ghost);c.restore()}}drawFighter(f);drawSpecial(f)}drawFireballs();drawBlades()}particles.forEach(p=>{c.globalAlpha=p.life/.28;c.fillStyle=p.color;c.fillRect(p.x,p.y,4,4)});c.globalAlpha=1;c.restore();c.restore();hud()}
let loadCount=0;const tasks=[];for(const type of['punch','dodge','jump','block','study']){images[type]=[[],[]];for(let row=0;row<2;row++)for(let frame=0;frame<6;frame++)tasks.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[type][row][frame]=im;loadCount++;$('start').textContent='CARICAMENTO '+Math.round(loadCount/61*100)+'%';resolve()};im.onerror=()=>reject(new Error(type+' '+row+' '+frame));im.src=`assets-alpha/${type}/${row}-${frame}.png`}))}
tasks.push(new Promise((resolve,reject)=>{if(scenery.complete&&scenery.naturalWidth){loadCount++;resolve()}else{scenery.onload=()=>{loadCount++;resolve()};scenery.onerror=()=>reject(new Error('Sfondo non caricato'))}}));for(const [id,path] of [['demone','assets-alpha/specials/dark-flame-orb-frames.webp?v=fireball6'],['ninja','assets-alpha/specials/shadow-energy-blade-frames.webp?v=lightblade2']])tasks.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{specialSheets[id]={img:im};resolve()};im.onerror=()=>{specialSheets[id]=null;resolve()};im.src=path}));for(const [id,folder] of [['demone','special-prep-demon'],['ninja','special-prep-ninja']])for(let frame=0;frame<4;frame++)tasks.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{specialPrep[id][frame]=im;resolve()};im.onerror=reject;im.src=`assets-alpha/${folder}/${frame}.webp`;}));
for(const [id,path] of [['demone','assets-alpha/defeat/demone.png?v=defeat1'],['ninja','assets-alpha/defeat/ninja.png?v=defeat1']])tasks.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{defeatSheets[id]={img:im};resolve()};im.onerror=()=>{defeatSheets[id]=null;resolve()};im.src=path}));Promise.all(tasks).then(()=>{loaded=true;$('start').disabled=false;$('start').textContent='ENTRA NELL’ARENA →';game.start({character:chosen});game.phase='menu';game.events=[];camera.reset(game.fighters);syncPads()}).catch(()=>{$('start').textContent='CARICAMENTO FALLITO — RICARICA';$('status').textContent='Alcuni fotogrammi non sono stati caricati. Ricarica la pagina per riprovare.'});
function loop(ms){const dt=Math.min((ms-last)/1000,.2);last=ms;const localInput=[{move:Number(!!keys.d)-Number(!!keys.a),block:!!keys.s},{move:Number(!!keys.arrowright)-Number(!!keys.arrowleft),block:!!keys.arrowdown}];const input=net.role==='host'?[localInput[0],net.remoteInput]:net.role==='guest'?[{move:0,block:false},localInput[1]]:localInput;net.input=input;let remaining=dt;while(remaining>0){const slice=Math.min(remaining,1/60);if(net.role!=='guest')game.update(slice,input);remaining-=slice;}events();if(!game.paused){updateFireballs(dt);updateBlades(dt)}if(net.onFrame)net.onFrame(game);if(game.fighters.length&&!game.paused)camera.update(game.fighters,dt);if(!game.paused){shake*=.8;flash=flash.map(v=>Math.max(0,v-dt));particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);toastT-=dt;if(toastT<=0)$('toast').textContent=''}render(ms/1000);requestAnimationFrame(loop)}requestAnimationFrame(loop);

function musicLabel(){$('music').textContent=music.enabled?(music.playing?'♫ Musica: accesa':'♫ Musica: pronta'):'♫ Musica: spenta';$('music').setAttribute('aria-pressed',String(music.enabled))}
